  return r;
};
const endOfWeek = (d) => {
  const r = new Date(d);
  r.setDate(r.getDate() + (6 - r.getDay()));
  r.setHours(0, 0, 0, 0);
  return r;
};
const addDays = (d, n) => {
  const r = new Date(d);
  r.setDate(r.getDate() + n);
  return r;
};
const isSameMonth = (a, b) => a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth();
const isSameDay = (a, b) => a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
const isToday = (d) => isSameDay(d, new Date());
const formatMonthYear = (d) => d.toLocaleString('en-US', { month: 'long', year: 'numeric' });
const formatTime = (d) => d.toLocaleString('en-US', { hour: 'numeric', minute: '2-digit' });
const formatFullDate = (d) => d.toLocaleString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });

const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

export const ShiftsCalendar = ({
  shifts = [],
  currentMonth = new Date(),
  onShiftClick = () => {},
  onMonthChange = () => {},
  className = '',
  style = {},
  maxVisibleShifts = 3,
}) => {
  useEffect(() => {
    if (typeof document === 'undefined') return;
    if (document.getElementById(STYLE_ID)) return;
    const styleEl = document.createElement('style');
    styleEl.id = STYLE_ID;
    styleEl.textContent = CALENDAR_CSS;
    document.head.appendChild(styleEl);
  }, []);

  const [viewMonth, setViewMonth] = useState(currentMonth);

  useEffect(() => {
    setViewMonth(currentMonth);
  }, [currentMonth]);

  const weeks = useMemo(() => {
    const monthStart = startOfMonth(viewMonth);
    const monthEnd = endOfMonth(viewMonth);
    const calStart = startOfWeek(monthStart);
    const calEnd = endOfWeek(monthEnd);

    const result = [];
    let cursor = calStart;
    while (cursor <= calEnd) {
      const week = [];
      for (let i = 0; i < 7; i++) {
        const date = addDays(cursor, i);
        week.push({
          date,
          isCurrentMonth: isSameMonth(date, viewMonth),
          isToday: isToday(date),
          shifts: shifts.filter((s) => isSameDay(new Date(s.start), date)),
        });
      }
      result.push(week);
      cursor = addDays(cursor, 7);
    }
    return result;
  }, [shifts, viewMonth]);

  const handlePrev = useCallback(() => {
    const next = new Date(viewMonth.getFullYear(), viewMonth.getMonth() - 1, 1);
    setViewMonth(next);
    onMonthChange(next);
  }, [viewMonth, onMonthChange]);

  const handleNext = useCallback(() => {
    const next = new Date(viewMonth.getFullYear(), viewMonth.getMonth() + 1, 1);
    setViewMonth(next);
    onMonthChange(next);
  }, [viewMonth, onMonthChange]);

  const handleShiftClick = useCallback((shift, e) => {
    e.stopPropagation();
    onShiftClick(shift, e);
  }, [onShiftClick]);

  const handleShiftKeyDown = useCallback((shift, e) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      onShiftClick(shift, e);
    }
  }, [onShiftClick]);

  return (
    <div
      className={`shifts-calendar-container ${className}`.trim()}
      style={style}
      role="grid"
      aria-label={`Shifts calendar for ${formatMonthYear(viewMonth)}`}
    >
      <header className="shifts-calendar-header">
        <button
          type="button"
          className="shifts-calendar-nav-button"
          onClick={handlePrev}
          aria-label="Previous month"
        >
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" aria-hidden="true">
            <path d="M15 18l-6-6 6-6" />
          </svg>
        </button>
        <h2 className="shifts-calendar-month-title">{formatMonthYear(viewMonth)}</h2>
        <button
          type="button"
          className="shifts-calendar-nav-button"
          onClick={handleNext}
          aria-label="Next month"
        >
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" aria-hidden="true">
            <path d="M9 18l6-6-6-6" />
          </svg>
        </button>
      </header>

      <div className="shifts-calendar-weekday-row" role="row">
        {WEEKDAYS.map((day) => (
          <div key={day} className="shifts-calendar-weekday-cell" role="columnheader">
            {day}
          </div>
        ))}
      </div>

      <div className="shifts-calendar-grid" role="rowgroup">
        {weeks.flat().map((cell, idx) => (
          <div
            key={idx}
            className={`shifts-calendar-day-cell${!cell.isCurrentMonth ? ' shifts-calendar-other-month' : ''}${cell.isToday ? ' shifts-calendar-today' : ''}`}
            role="gridcell"
            aria-label={formatFullDate(cell.date)}
          >
            <span className="shifts-calendar-day-number">{cell.date.getDate()}</span>
            <div className="shifts-calendar-shift-list" role="list">
              {cell.shifts.slice(0, maxVisibleShifts).map((shift) => (
                <button
                  key={shift.id}
                  type="button"
                  className="shifts-calendar-shift-block"
                  style={{ backgroundColor: shift.color || '#1a73e8' }}
                  onClick={(e) => handleShiftClick(shift, e)}
                  onKeyDown={(e) => handleShiftKeyDown(shift, e)}
                  title={`${shift.title} — ${formatTime(new Date(shift.start))} - ${formatTime(new Date(shift.end))}`}
                  aria-label={`${shift.title}, ${formatTime(new Date(shift.start))} to ${formatTime(new Date(shift.end))}`}
                >
                  {shift.title}
                </button>
              ))}
              {cell.shifts.length > maxVisibleShifts && (
                <span className="shifts-calendar-more-indicator" role="listitem">
                  +{cell.shifts.length - maxVisibleShifts} more
                </span>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default ShiftsCalendar;
```

