```javascript
// src/components/RevenueOverview.jsx
import React from 'react';
import {
  ComposedChart,
  Bar,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
} from 'recharts';
import { Box, Paper, Typography } from '@mui/material';

const Y_AXIS_ID_REVENUE = 'revenue';
const Y_AXIS_ID_ORDERS = 'orders';

/**
 * Formats revenue values for Axis Ticks and Tooltips.
 * @param {number} value
 * @returns {string}
 */
const formatRevenue = (value) => {
  if (value >= 1e6) return `$${(value / 1e6).toFixed(1)}M`;
  if (value >= 1e3) return `$${(value / 1e3).toFixed(0)}k`;
  return `$${value}`;
};

/**
 * Formats order values for Axis Ticks and Tooltips.
 * @param {number} value
 * @returns {string}
 */
const formatOrders = (value) => {
  if (value >= 1e3) return `${(value / 1e3).toFixed(1)}k`;
  return `${value}`;
};

/**
 * Custom Tooltip Formatter for shared tooltip.
 * Recharts passes (value, name, props) where props.payload contains all series data for that x-position.
 */
const tooltipFormatter = (value, name, props) => {
  const payload = props?.payload || [];
  const revenueEntry = payload.find((p) => p.dataKey === 'revenue');
  const ordersEntry = payload.find((p) => p.dataKey === 'orders');

  // This formatter is called per series. We only return formatted string for the active series.
  // However, Recharts shared tooltip calls formatter for each line item.
  // We identify series by dataKey (set on Bar/Line).
  const dataKey = props?.dataKey || name; 

  if (dataKey === 'revenue' || (revenueEntry && dataKey === revenueEntry.name)) {
    return [formatRevenue(value), 'Revenue'];
  }
  if (dataKey === 'orders' || (ordersEntry && dataKey === ordersEntry.name)) {
    return [formatOrders(value), 'Orders'];
  }
  return [value, name];
};

const RevenueOverview = ({
  data = [],
  revenueLabel = 'Revenue',
  ordersLabel = 'Orders',
  revenueColor = '#8884d8',
  ordersColor = '#82ca9d',
  height = 300,
  title,
}) => {
  // Guard against empty data to prevent Recharts domain errors
  const hasData = Array.isArray(data) && data.length > 0;

  return (
    <Box sx={{ width: '100%', overflow: 'hidden' }}>
      <Paper elevation={1} sx={{ p: 2, height: '100%', display: 'flex', flexDirection: 'column' }}>
        {title && (
          <Typography variant="h6" component="div" sx={{ mb: 2, fontWeight: 600 }}>
            {title}
          </Typography>
        )}
        <Box
          data-testid="revenue-overview-chart"
          sx={{ flex: 1, minHeight: 0, position: 'relative' }} 
        >
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart data={data} layout="vertical" margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} opacity={0.3} />

              {/* X Axis (Categories) - Bottom */}
              <XAxis
                type="category"
                dataKey="name"
                tickLine={false}
                axisLine={false}
                tick={{ fontSize: 12, fill: '#666' }}
                dy={10}
              />

              {/* Y Axis Left: Revenue */}
              <YAxis
                yAxisId={Y_AXIS_ID_REVENUE}
                orientation="left"
                tickFormatter={formatRevenue}
                tick={{ fontSize: 12, fill: revenueColor }}
                axisLine={{ stroke: revenueColor }}
                tickLine={{ stroke: revenueColor }}
                // domain={['auto', 'auto']} // Default behavior, explicit for clarity
                width={80} // Reserve space for currency labels
              />

              {/* Y Axis Right: Orders */}
              <YAxis
                yAxisId={Y_AXIS_ID_ORDERS}
                orientation="right"
                tickFormatter={formatOrders}
                tick={{ fontSize: 12, fill: ordersColor }}
                axisLine={{ stroke: ordersColor }}
                tickLine={{ stroke: ordersColor }}
                // domain={['auto', 'auto']} // Independent calculation
                width={60} // Reserve space for order labels
              />

              <Tooltip
                shared
                formatter={tooltipFormatter}
                contentStyle={{
                  backgroundColor: '#fff',
                  border: '1px solid #e0e0e0',
                  borderRadius: '8px',
                  boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
                }}
                labelFormatter={(label) => <span style={{ fontWeight: 600, color: '#333' }}>{label}</span>}
              />

              <Legend
                wrapperStyle={{ paddingTop: '10px' }}
                formatter={(value) => value} // Use names from components
              />

              {/* Revenue Bars - Bound to Left Axis */}
              <Bar
                yAxisId={Y_AXIS_ID_REVENUE}
                dataKey="revenue"
                name={revenueLabel}
                fill={revenueColor}
                radius={[4, 4, 0, 0]}
                maxBarSize={40}
                barSize={30}
              />

              {/* Orders Line - Bound to Right Axis */}
              <Line
                yAxisId={Y_AXIS_ID_ORDERS}
                type="monotone"
                dataKey="orders"
                name={ordersLabel}
                stroke={ordersColor}
                strokeWidth={2.5}
                dot={{ r: 4, strokeWidth: 2, stroke: ordersColor, fill: '#fff' }}
                activeDot={{ r: 6, stroke: ordersColor, fill: '#fff' }}
              />
            </ComposedChart>
          </ResponsiveContainer>
        </Box>
      </Paper>
    </Box>
  );
};

export default RevenueOverview;
```

