 * Formats revenue values for Axis Ticks and Tooltips.
 * @param {number} value
 * @returns {string}
 */
const formatRevenue = (value) => {
  if (value >= 1e6) return `$${(value / 1e6).toFixed(1)}M`;
  if (value >= 1e3) return `$${(value / 1e3).toFixed(0)}k`;
  return `$${value}`;
};

/**
 * Formats order values for Axis Ticks and Tooltips.
 * @param {number} value
 * @returns {string}
 */
const formatOrders = (value) => {
  if (value >= 1e3) return `${(value / 1e3).toFixed(1)}k`;
  return `${value}`;
};

/**
 * Custom Tooltip Formatter for shared tooltip.
 * Recharts passes (value, name, props) where props.payload contains all series data for that x-position.
 */
const tooltipFormatter = (value, name, props) => {
  const payload = props?.payload || [];
  const revenueEntry = payload.find((p) => p.dataKey === 'revenue');
  const ordersEntry = payload.find((p) => p.dataKey === 'orders');

  // This formatter is called per series. We only return formatted string for the active series.
  // However, Recharts shared tooltip calls formatter for each line item.
  // We identify series by dataKey (set on Bar/Line).
  const dataKey = props?.dataKey || name; 

  if (dataKey === 'revenue' || (revenueEntry && dataKey === revenueEntry.name)) {
    return [formatRevenue(value), 'Revenue'];
  }
  if (dataKey === 'orders' || (ordersEntry && dataKey === ordersEntry.name)) {
    return [formatOrders(value), 'Orders'];
  }
  return [value, name];
};

